const CASES=[{"cards": [{"id": 47, "pos": "对方的心情", "rev": false}, {"id": 6, "pos": "自己的状况", "rev": false}, {"id": 15, "pos": "相处方式", "rev": false}, {"id": 18, "pos": "周遭环境", "rev": false}, {"id": 13, "pos": "关系结果", "rev": false}], "cat": "感情", "conclusion": "牌面显示他确有回头意（圣杯骑士），但恶魔＋月亮警告：这段关系的问题一个都没解决。建议先别急着答应复合，用恋人\"选择\"的姿态跟他谈一次——把相处模式、联系频率、底线都谈清楚再说；谈不清，这次复合只是下一轮拉扯的开始。", "id": "c1", "question": "分手三个月了，他偶尔还会联系我，到底还想不想复合？", "scan": "大牌占 4/5，分量很重——这不是\"聊不聊得来\"的小事，是整段关系的课题级转折；花色上圣杯（情）配恶魔（执念）加月亮（恐惧），情绪浓度极高；全正位，局势正在按它自己的方向推进。", "source": "练习案例 · 虚构示意", "spread_id": "s6", "steps": ["对方的心情 · 圣杯骑士：他是真的还有感觉——骑士带着花来，是浪漫和示好；但骑士也代表\"来得快去得也快\"，要看后续行动，别只看姿态。", "自己的状况 · 恋人：你正站在岔路口——选复合还是彻底翻篇，这道选择题其实是你自己要先答的。", "相处方式 · 恶魔：你们的互动模式有执念成分——放不下、反复拉扯；牌提醒你先分清这是爱，还是不甘心。", "周遭环境 · 月亮：外界信息很乱（朋友转述、社交动态脑补），很多\"他好像还想\"可能是月光下的影子，先分清想象和现实。", "关系结果 · 死神：无论复合与否，旧模式必须结束——要么带着新规则重新开始，要么彻底告别，没有\"回到从前\"的选项。"], "title": "复合：他还想回头吗"}, {"cards": [{"id": 7, "pos": "求问者现况", "rev": false}, {"id": 10, "pos": "选甲的近况", "rev": false}, {"id": 0, "pos": "选乙的近况", "rev": false}, {"id": 8, "pos": "选甲的未来", "rev": false}, {"id": 3, "pos": "选乙的未来", "rev": false}], "cat": "事业", "conclusion": "两条路都是顺的（全正位）：留＝稳中带变的慢收益，走＝高波动高回报。建议问自己一个问题：现阶段更想要\"确定性\"还是\"可能性\"？想要可能性，愚人＋女皇的组合值得赌——但入职前先把行业基本功的补课计划列好，别裸跳。", "id": "c2", "question": "现在的公司稳定但没成长，新公司涨薪 30% 但要去陌生行业，该怎么选？", "scan": "大牌 5/5 全满——这是未来两三年的职业方向级选择，值得认真对待；全正位，两条路都走得通，区别只在节奏和代价。", "source": "练习案例 · 虚构示意", "spread_id": "s5", "steps": ["求问者现况 · 战车：你现在的状态是\"拉得动\"——意志和执行力都在线，不缺闯的资本，缺的只是一个方向。", "选甲的近况（留现公司）· 命运之轮：轮子正在转，内部可能有调岗或新项目的机会出现，稳定里藏着变量。", "选乙的近况（去新公司）· 愚人：全新的开始，凭直觉跳出去会有惊喜；但愚人也意味着\"没地图\"——行业陌生是真实成本。", "选甲的未来（留下）· 力量：走的是慢功夫——用耐心驯服现状，一年后你会感谢现在的沉住气，但过程不刺激。", "选乙的未来（去）· 女皇：新土壤能开花结果，付出进入收获期——前提是你熬得过愚人阶段的开荒期。"], "title": "跳槽：留还是走"}, {"cards": [{"id": 1, "pos": "过去", "rev": false}, {"id": 9, "pos": "现在", "rev": false}, {"id": 19, "pos": "未来", "rev": false}], "cat": "学业", "conclusion": "不用换方法，换节奏：把 10 小时拆成\"学—复盘—休息\"的循环，隐士牌明确说抽离一下效率更高。方向没错，坚持到太阳。", "id": "c3", "question": "备考到瓶颈期了，每天学 10 小时但效率很低，要不要换学习方法？", "scan": "全大牌 3/3——这是\"学习观\"层面的课题，不是换个 App 就能解决的；全正位，方向没错，问题在节奏。", "source": "练习案例 · 虚构示意", "spread_id": "s3", "steps": ["过去 · 魔术师：你开局是对的——资料、计划、方法都齐了，万事俱备才走到今天，不是运气。", "现在 · 隐士：瓶颈期的正解是隐士式的\"向内\"：减少输入、增加复盘，把刷题时间分一半给整理错题和复述。", "未来 · 太阳：牌给的是高光结局——但太阳照的是\"持续做对的事\"的人，不是\"熬时长\"的人。"], "title": "考研冲刺：这三个月怎么安排"}, {"cards": [{"id": 11, "pos": "问题现况", "rev": false}, {"id": 15, "pos": "障碍或援助", "rev": true}, {"id": 2, "pos": "理想状况", "rev": false}, {"id": 12, "pos": "本意", "rev": false}, {"id": 20, "pos": "过去状况", "rev": false}, {"id": 16, "pos": "未来状况", "rev": false}, {"id": 33, "pos": "你的现况", "rev": false}, {"id": 14, "pos": "周围环境", "rev": false}, {"id": 17, "pos": "你的愿望", "rev": false}, {"id": 21, "pos": "最后结果", "rev": false}], "cat": "感情", "conclusion": "可以继续，但把节奏交给女祭司：观察代替审判。塔的那一下（发现他真实的样子）迟早会来，提前知道它是\"去幻存真\"而不是\"塌房\"，到时候就不会慌。建议未来两个月多看他处理分歧的方式，少看他说的话。", "id": "c4", "question": "刚认识两个月，他对我很好，但总觉得看不透，能继续投入吗？", "scan": "大牌 9/10——这段关系对你而言是课题级的，牵动很深；恶魔逆＋塔正：藏着一段\"看清真相→结构震动\"的过程；但收尾是星星＋世界，希望和圆满都在，震荡是过程不是结局。", "source": "练习案例 · 虚构示意", "spread_id": "s8", "steps": ["问题现况 · 正义：这段关系目前是公平的——付出和回馈对等，他的好是真实的。", "障碍或援助 · 恶魔逆：好消息——你正在挣脱\"看不透就脑补最坏\"的旧模式，看清的能力在恢复。", "理想状况 · 女祭司：别急着要答案，再观察一阵，你的直觉正在收集信息。", "本意 · 倒吊人：你内心真正想要的不是\"他靠不靠谱\"的判决，而是学会在关系里换位看人。", "过去状况 · 审判：你刚从上一段感情的课题里醒过来，带着新标准在看人——标准高是好事。", "未来状况 · 塔：会有一次\"幻灭\"时刻——可能是发现他不如想象中完美，冲击不小，但这是必经的去幻过程。", "你的现况 · 权杖骑士：你是行动派心态，想快点有个结论——骑士的急躁恰恰是需要按住的部分。", "周围环境 · 节制：朋友们的看法是调和的，没人强烈反对，环境不添乱。", "你的愿望 · 星星：你想要的是\"被温柔以待的确定感\"，这个愿望本身没问题。", "最后结果 · 世界：走完这个认知过程，关系能进入一个完整的新阶段——圆满，但\"新阶段\"不等于\"和最初幻想的一样\"。"], "title": "新恋情：他靠谱吗"}, {"cards": [{"id": 4, "pos": "第一张", "rev": false}, {"id": 5, "pos": "第二张", "rev": true}, {"id": 10, "pos": "第三张", "rev": true}], "cat": "选择", "conclusion": "想走自己的路没错（教皇逆），能力也够（皇帝），但时机不对（命运之轮逆）。建议别 all in，先以最小成本验证——副业或兼职合伙跑三个月，等轮子转上来再下注。", "id": "c5", "question": "有个创业机会找我合伙，但要降薪 all in，值得赌吗？", "scan": "3 张全大牌——人生方向级的问题；教皇逆＋命运之轮逆：现在不是\"天时\"，但\"人和\"（皇帝）是齐的。", "source": "练习案例 · 虚构示意", "spread_id": "s2", "steps": ["第一张 · 皇帝：你手里的牌是秩序和执行力——这是创业最稀缺的素质，你有。", "第二张 · 教皇逆：常规路径（继续打工升职）对你已经没吸引力了，想走自己的路是真实的。", "第三张 · 命运之轮逆：但轮子现在在低谷——行业、时机、资金至少一样还没转到位，all in 的代价会比预想大。"], "title": "创业还是继续打工"}, {"cards": [{"id": 5, "pos": "问题核心", "rev": false}, {"id": 7, "pos": "障碍或短处", "rev": true}, {"id": 8, "pos": "对策", "rev": false}, {"id": 11, "pos": "资源或长处", "rev": false}], "cat": "事业", "conclusion": "赢面在\"稳\"不在\"奇\"：按教皇的路子准备材料（数据＋流程＋结果），用力量的节奏稳住心态。答辩前一周别再加新内容了，战车逆警告：贪多会翻车。", "id": "c6", "question": "下个月升职答辩，竞争对手很强，我该怎么准备才能赢？", "scan": "大牌 4/4——这是\"职业身份\"级的事件；战车逆是唯一的逆位，也是整局的题眼：问题不在能力，在状态。", "source": "练习案例 · 虚构示意", "spread_id": "s4", "steps": ["问题核心 · 教皇：这次答辩看的是\"是否走正道\"——业绩、流程、合规，评委要的是稳妥可信，不是花活。", "障碍或短处 · 战车逆：你现在有点被焦虑牵着走——准备时东一榔头西一棒子，方向盘打滑。", "对策 · 力量：别跟焦虑硬碰硬——把准备拆成每天一小块，用耐心驯服它；答辩现场温和坚定比气场全开更打动人。", "资源或长处 · 正义：你过去的成绩是实打实的，因果不亏待人——把\"做了什么、带来什么结果\"一条条摆出来，就是最强的牌。"], "title": "升职答辩：怎么准备"}, {"cards": [{"id": 12, "pos": "指引", "rev": true}], "cat": "综合", "conclusion": "今天先按兵不动，把方案再打磨一轮。等对方主动释放信号（或换个他状态好的日子），倒吊人转正时再去，一次谈成。", "id": "c7", "question": "有个合作想今天去谈，但心里没底，今天去合适吗？", "scan": "单张牌，直指核心——逆位的倒吊人是今天的全部信息：别硬来。", "source": "练习案例 · 虚构示意", "spread_id": "s1", "steps": ["指引 · 倒吊人逆：今天不适合\"主动推进\"——逆位说的是\"越挣扎越糟\"：对方现在没在听的频道上，去了也谈不出结果，反而显得急。"], "title": "单牌：今天适合主动推进那件事吗"}, {"cards": [{"id": 2, "pos": "我的心态", "rev": true}, {"id": 38, "pos": "对方的心态", "rev": false}, {"id": 6, "pos": "过去", "rev": false}, {"id": 18, "pos": "现在", "rev": true}, {"id": 21, "pos": "未来发展", "rev": true}, {"id": 14, "pos": "环境", "rev": false}], "cat": "感情", "conclusion": "牌没有判死刑（世界逆≠世界碎），但女祭司逆点名了你：先诚实面对自己到底还想不想要。建议别在微信里谈，约一次见面，把\"你还想继续吗\"摆到桌面上——答案你们俩都有，只是都没说。", "id": "c8", "question": "异地一年了，见面越来越少，感觉在慢慢变淡，还要坚持吗？", "scan": "大牌 5/6——感情课题，分量不轻；月亮逆是转折点：之前很多\"变淡了\"的感觉，正在被证实或证伪；世界逆收尾：差一口气，但\"差一口气\"本身也是答案的一部分。", "source": "练习案例 · 虚构示意", "spread_id": "s7", "steps": ["我的心态 · 女祭司逆：你其实已经有答案了，只是不愿听——逆位说你在用忙碌盖住直觉。", "对方的心态 · 圣杯三：他在那边的生活是热闹的（朋友、社交），不是不爱，是\"异地\"这件事在他生活里的权重在下降。", "过去 · 恋人：你们是认真选择过彼此的，这段感情的起点是真的。", "现在 · 月亮逆：好消息——迷雾在散，你会越来越看清这段关系的真实样子，不再靠脑补。", "未来发展 · 世界逆：按现在这样下去，圆满差一口气——不是没可能，是需要有人先把\"那口气\"补上（一次长谈、一次见面、一个决定）。", "环境 · 节制：外部没有阻力，没人反对、没有第三者，问题纯粹在你们两人之间。"], "title": "异地恋：这段关系走得下去吗"}, {"cards": [{"id": 4, "pos": "问题核心", "rev": true}, {"id": 7, "pos": "障碍或短处", "rev": true}, {"id": 1, "pos": "对策", "rev": false}, {"id": 3, "pos": "资源或长处", "rev": false}], "cat": "事业", "conclusion": "别立威，立功。皇帝逆＋女皇正的组合拳是：收起\"我是领导\"的架子（皇帝逆），用\"跟着我有肉吃\"带团队（女皇＋魔术师）。三个月后，他们服的是你的战绩，不是你的职位。", "id": "c9", "question": "刚升管理岗，团队里几个老员工不太服我，怎么立威又不伤和气？", "scan": "大牌 4/4——这是\"领导力\"课题；皇帝逆＋战车逆连在一起：问题不在他们刺头，在你\"想立威\"这个念头本身用力过猛了。", "source": "练习案例 · 虚构示意", "spread_id": "s4", "steps": ["问题核心 · 皇帝逆：你现在的模式是\"怕管不住所以先绷紧\"——逆位皇帝警告：越用力证明权威，越容易变成大家眼里的\"官威\"。", "障碍或短处 · 战车逆：方向盘在打滑——你想快点出成绩证明自己，反而让团队觉得你只顾自己。", "对策 · 魔术师：你手里其实什么都有——专业能力、老板的信任、对业务的理解。魔术师的做法是\"展示\"不是\"证明\"：带着他们打一场胜仗，比开十次会管用。", "资源或长处 · 女皇：你真正的武器是滋养——多给资源、多给露脸机会，老员工要的是被尊重，不是被管。"], "title": "带团队：怎么管住几个刺头"}, {"cards": [{"id": 10, "pos": "过去", "rev": true}, {"id": 12, "pos": "现在", "rev": false}, {"id": 17, "pos": "未来", "rev": false}], "cat": "综合", "conclusion": "允许自己迷茫一阵子（倒吊人），这是修复期不是摆烂期。建议每天只做一件让自己\"有点感觉\"的小事（散步、做饭、整理），星星牌的承诺是——方向会在你恢复感知的过程中自己浮现。", "id": "c10", "question": "工作和生活都提不起劲，不知道自己到底想要什么，该怎么办？", "scan": "全大牌——这是人生阶段课题，不是\"换个爱好\"能解决的；但牌序是低谷→悬置→星星，方向是向上的。", "source": "练习案例 · 虚构示意", "spread_id": "s3", "steps": ["过去 · 命运之轮逆：你刚从一段低谷里出来——运气、机会、状态都掉过，现在是冬天的尾巴，不是你\"废了\"。", "现在 · 倒吊人：别急着\"振作起来\"——倒吊人说，现在最好的姿势就是悬着：少做决定，多观察，把视角倒过来看看自己到底在为什么累。", "未来 · 星星：星星在终点等着——风雨后的宁静会回来，但星星只照给\"熬过黑夜\"的人，急不来。"], "title": "迷茫期：下一步往哪走"}, {"id": "c11", "title": "复合抉择：回头，还是往前走", "question": "分手半年了，前任最近带着改变回来了，说想重新开始；可我这边也有个聊得不错的新人，到底该回头还是往前走？", "cat": "感情", "spread_id": "s5", "cards": [{"id": 51, "pos": "求问者现况", "rev": false}, {"id": 20, "pos": "选甲的近况（接受复合）", "rev": false}, {"id": 13, "pos": "选乙的近况（往前走）", "rev": false}, {"id": 37, "pos": "选甲的未来", "rev": false}, {"id": 17, "pos": "选乙的未来", "rev": false}], "steps": ["求问者现况 · 宝剑二：你不是没感觉，是两个选项都有道理所以动不了——蒙着眼僵持，越想越乱。", "选甲的近况（接受复合）· 审判：回头这条路带着“召唤”的意味——但审判提醒你，要听的是他行动的证据，不是道歉的音量。他到底为“改变”付出了什么具体代价？", "选乙的近况（往前走）· 死神：往前走意味着旧关系彻底落幕——死神在这里不是坏牌，是“翻篇”的仪式感，旧的不去新的不来。", "选甲的未来（接受复合）· 圣杯二：复合能回到平等对话——但前提是审判那关过了：他真的变了，否则圣杯二只是下一轮拉扯的开场。", "选乙的未来（往前走）· 星星：往前走是修复期——慢，但方向是亮的，星星照的是愿意先照顾好自己的人。"], "scan": "大牌 3/5，审判、死神、星星三张大牌同局——这是“旧我 vs 新我”的课题级抉择；全正位，两条路都走得通，区别只在你要为什么买单。", "conclusion": "两条路都通，别急着二选一。给他设一个 30 天观察期：看他为“改变”做了什么具体的事（不是说了什么）。30 天后如果还是只有嘴，选乙往前走；如果有行动，审判才算数，再谈复合不迟。", "source": "练习案例 · 虚构示意"}, {"id": "c12", "title": "跳槽：大厂 offer，接还是不接", "question": "拿到了大厂 offer，涨薪 40% 但听说强度很大；现公司最近又在传裁员，该赌一把还是苟住？", "cat": "事业", "spread_id": "s5", "cards": [{"id": 9, "pos": "求问者现况", "rev": false}, {"id": 7, "pos": "选甲的近况（去大厂）", "rev": false}, {"id": 16, "pos": "选乙的近况（留现公司）", "rev": false}, {"id": 19, "pos": "选甲的未来", "rev": true}, {"id": 10, "pos": "选乙的未来", "rev": true}], "steps": ["求问者现况 · 隐士：你现在是“向内看”的状态——offer 和裁员传闻都是外部噪音，先问自己这两年到底要什么，再选不迟。", "选甲的近况（去大厂）· 战车：去大厂＝主动出击，你的执行力拉得动这辆车；但战车也意味着“停不下来”，强度传闻大概率是真的。", "选乙的近况（留现公司）· 塔：留下不是“苟住”，是塔——裁员传闻大概率是真的，被动等来的震荡，比主动选的苦更难受。", "选甲的未来（去大厂）· 太阳逆：一年后有成绩，但“太阳打了折”——钱和 title 都有，健康和生活要付账。先问自己愿不愿意付这笔账，再签字。", "选乙的未来（留现公司）· 命运之轮逆：留下就是把方向盘交给别人——轮子不转，你只能等，等来的是什么不由你定。"], "scan": "大牌 5/5，塔和太阳逆同局——这不是“选 A 还是选 B”的问题，是“主动吃苦还是被动挨打”的问题。", "conclusion": "牌建议“主动吃苦”：去大厂。但设两条止损线：入职前跟直属 leader 谈清楚团队真实节奏；给自己 12 个月观察期，太阳逆警告的是“透支”不是“失败”，透支了就撤。留下的塔，是躲不掉的。", "source": "练习案例 · 虚构示意"}, {"id": "c13", "title": "合伙开店：发小这局靠谱吗", "question": "发小拉我合伙开社区咖啡店，他出 60% 资金、我出技术和运营，股权五五开，靠谱吗？", "cat": "选择", "spread_id": "s4", "cards": [{"id": 15, "pos": "问题核心", "rev": false}, {"id": 16, "pos": "障碍或短处", "rev": true}, {"id": 9, "pos": "对策", "rev": false}, {"id": 4, "pos": "资源或长处", "rev": false}], "steps": ["问题核心 · 恶魔：核心是利益绑定——五五开听着公平，但“他出钱你出力”里，钱是显性的，你的技术和时间是隐性的；恶魔提醒你，把隐性投入也明码标价。", "障碍或短处 · 塔逆：障碍是“被粉饰过的隐患”——“肯定赚钱”“房东是我亲戚”这类话，塔逆说别全信，塌的部分可能被话术糊住了。", "对策 · 隐士：对策是慢——别在饭桌上签字。隐士的做法：自己去那条街蹲三天，看人流、看竞品、算账，拿数据回来再谈条件。", "资源或长处 · 皇帝：你的资源是规则感——你是能把店开起来的人；皇帝也说：合伙前先把退出机制写进协议（谁干不下去怎么散伙），这是你的护身符。"], "scan": "4 张全是大牌，恶魔＋塔逆同局——这局的题眼是“被美化过的风险”；隐士是唯一的解：慢，就是快。", "conclusion": "项目可以谈，条件要重写：① 你的技术入股折价写进协议，别只拿干股口头承诺；② 先签 3 个月试运营，跑通再谈长期；③ 退出机制先小人后君子。塔逆不反对创业，反对的是“闭眼签字”。", "source": "练习案例 · 虚构示意"}, {"id": "c14", "title": "读研：换研究方向吗", "question": "研二了，导师让我沿着现在的量化方向发论文，但我真正想做的是偏质性的田野方向，要不要换？", "cat": "学业", "spread_id": "s3", "cards": [{"id": 1, "pos": "过去", "rev": false}, {"id": 0, "pos": "现在", "rev": false}, {"id": 21, "pos": "未来", "rev": false}], "steps": ["过去 · 魔术师：你量化基本功是扎实的——这不是白学的，是你换方向的底气，不是沉没成本。", "现在 · 愚人：愚人站在“现在”，说明你已经在悬崖边了——想换是真的；但愚人也提醒：别为了“反抗导师”而换，要为了“真想做”而换，动机要干净。", "未来 · 世界：换过去能走完一个完整的周期——世界牌说这条路能自洽，但“走完”需要你把量化的基本功带过去做混合研究，而不是全盘扔掉。"], "scan": "3 张全大牌——这是学术身份级的选择；愚人在“现在”位：你想换的可能不只是方向，是“被安排的人生”。", "conclusion": "可以换，但别“裸换”：跟导师谈“混合方法”的方案（量化打底＋质性增量），既保毕业又遂心愿。愚人＋世界＝带着家当去流浪，不是净身出户。", "source": "练习案例 · 虚构示意"}, {"id": "c15", "title": "和妈妈冷战：春节怎么破冰", "question": "因为工作的事跟我妈冷战两周了，过年回家怎么破冰？她总想让我回老家考公。", "cat": "家庭", "spread_id": "s6", "cards": [{"id": 48, "pos": "对方的心情（妈妈）", "rev": true}, {"id": 8, "pos": "自己的状况", "rev": true}, {"id": 14, "pos": "相处方式", "rev": true}, {"id": 73, "pos": "周遭环境", "rev": false}, {"id": 19, "pos": "关系结果", "rev": false}], "steps": ["对方（妈妈）的心情 · 圣杯王后逆：她不是不爱你，是焦虑淹没了表达——逆位的王后把关心煮成了唠叨和控制，听着刺耳，本意是怕。", "自己的状况 · 力量逆：你也在硬撑——表面上“我没事”，其实每次通话都在攒火；力量逆说别再靠意志力憋了，憋久了会爆。", "相处方式 · 节制逆：你们现在的模式是“各说各话”——她讲稳定，你讲自我实现，倒不到一个杯子里，越谈越凉。", "周遭环境 · 钱币十：亲戚们的“为你好”是放大器——别在家庭群里谈这事，舆论场只会让她更要面子，谈话阵地选一对一。", "关系结果 · 太阳：太阳收尾——春节是破冰窗口，真诚＋具体就能回暖；她要的不是你考公，是亲眼确认你过得好。"], "scan": "大牌 3/5，节制逆＋太阳收尾——关系没坏，是“频道”坏了；钱币十点名：这事不只你们母女，还有亲戚舆论场在场。", "conclusion": "别试图“说服”她，改成“展示”：带她去你工作的地方看看、见见你靠谱的朋友，让她亲眼看到你过得好，比一百句“我很好”管用。谈话只一对一，别在亲戚面前谈，太阳牌只照真诚的人。", "source": "练习案例 · 虚构示意"}, {"id": "c16", "title": "体检红灯：作息和奶茶怎么戒", "question": "体检查出轻度脂肪肝，医生让早睡＋戒奶茶，但我是个夜猫子外卖党，怎么改才坚持得下去？", "cat": "健康", "spread_id": "s4", "cards": [{"id": 15, "pos": "问题核心", "rev": true}, {"id": 18, "pos": "障碍或短处", "rev": false}, {"id": 14, "pos": "对策", "rev": false}, {"id": 17, "pos": "资源或长处", "rev": false}], "steps": ["问题核心 · 恶魔逆：好消息先说——链子是松的。你不是戒不掉，是“想一次戒掉”这个执念把你困住了，放下“明天就变好”的剧本。", "障碍或短处 · 月亮：真正的对手不是奶茶，是深夜——熬夜时的孤独和放空感才是你舍不得的东西；先承认这部分，再谈习惯，不然戒了奶茶还会有下一个。", "对策 · 节制：别搞“明天开始早睡早起”的休克疗法——节制的做法是每周只改一件事：这周奶茶减半，下周提前半小时睡，水滴式调整才留得住。", "资源或长处 · 星星：星星是倒水的人——不催、不逼，只是把水慢慢倒回池子里。你的长处是底子还在、意愿也真：作息乱成这样，你没有拖着不管，而是来认真想这件事怎么做。星星不给结果打包票，它只说一件事：慢慢往回倒的节奏，是能长期走下去的节奏。身体指标怎么变，定期复查该去还去、听医生的——那是医生的事，牌只负责陪你把习惯这头稳住。"], "scan": "大牌 4/4，恶魔逆＋月亮＋节制＋星星——这局讲的不是“自律”，是“和解”：链子是松的（恶魔逆），难的是深夜的情绪（月亮）。", "conclusion": "把目标从“变成自律的人”换成“每周改一件小事”。先处理月亮：睡前 1 小时放下手机，用播客或书替代刷视频的快感；奶茶和外卖自然跟着降。身体那边交给定期复查和医生判断，牌不替医生下结论——星星只照给开始行动的人：你负责把节奏立住，变化慢慢看。", "source": "练习案例 · 虚构示意"}, {"id": "c17", "title": "婚姻危机：离婚还是修复", "question": "结婚 6 年，激情早没了，婆媳矛盾不断，他工作忙长期缺席家庭，离婚还是再修一修？", "cat": "感情", "spread_id": "s8", "cards": [{"id": 53, "pos": "问题现况", "rev": false}, {"id": 38, "pos": "障碍或援助", "rev": true}, {"id": 45, "pos": "理想状况", "rev": false}, {"id": 2, "pos": "本意", "rev": true}, {"id": 6, "pos": "过去状况", "rev": true}, {"id": 14, "pos": "未来状况", "rev": false}, {"id": 58, "pos": "你的现况", "rev": false}, {"id": 69, "pos": "周围环境", "rev": true}, {"id": 17, "pos": "你的愿望", "rev": false}, {"id": 20, "pos": "最后结果", "rev": false}], "steps": ["问题现况 · 宝剑四：这段婚姻正在“休战期”——不是打架了，是连打的力气都没了；宝剑四说，先停手，再谈判。", "障碍或援助 · 圣杯三逆：最大的障碍是“没有盟友”——朋友们各有立场，婆媳各拉一派，你在中间孤立无援；但逆位也提醒，别在外人面前审判这段婚姻。", "理想状况 · 圣杯十：你想要的是完整的家，不是搭伙——这个愿望很正，但它要的是两个人都回来，不是你一个人补位。", "本意 · 女祭司逆：你内心其实已经偏向“不想修了”，只是怕做了决定会后悔——逆位说，先诚实，别急着判。", "过去状况 · 恋人逆：当初的选择就有勉强成分——为年龄、为催婚结的，恋人逆埋的是今天的雷，不是今天才坏的。", "未来状况 · 节制：修复的路是“慢慢调”——节制是水滴功夫，没有戏剧性和解，只有日复一日的重新配合。", "你的现况 · 宝剑九：你已经失眠一阵子了——牌把你的状态摆上台面：先照顾自己的神经，再谈婚姻的死活。", "周围环境 · 钱币六逆：家庭经济和付出是不对等的——钱谁出、家务谁做、孩子谁带，账面一直没平过，这是火药桶。", "你的愿望 · 星星：你还相信“能好起来”——星星不是幻想，它照的是愿意先把自己修好的人。", "最后结果 · 审判：无论离还是修，都要经过一次“清算”——把钱、孩子、各自的底线摊开谈一次，审判之后才有新生。"], "scan": "大牌 5/10——这是人生结构级的课题；宝剑九点名求问者先自救；审判收尾：这局没有“拖着”的选项，清算不可避免。", "conclusion": "牌不判离也不判留，它判的是“先谈判，再决定”。建议三步：① 先处理自己的失眠和情绪（宝剑九）；② 把经济账和分工账摊开谈一次（钱币六逆）；③ 给彼此 3 个月“节制式”修复期：每周一次认真谈话，有改善就续，没改善就带着审判的清醒走。离或不离，都别在不清醒的时候决定。", "source": "练习案例 · 虚构示意"}, {"id": "c18", "title": "暗恋：要不要表白", "question": "暗恋同部门的同事快一年了，感觉他对我也有点意思，要不要捅破这层窗户纸？", "cat": "感情", "spread_id": "s2", "cards": [{"id": 60, "pos": "第一张", "rev": false}, {"id": 46, "pos": "第二张", "rev": false}, {"id": 58, "pos": "第三张", "rev": true}], "steps": ["第一张 · 宝剑侍从：他对你是“有好奇的”——侍从的目光是试探性的，说明窗户纸没你想的那么厚，但也没捅破。", "第二张 · 圣杯侍从：好感的底子是真的——圣杯侍从是青涩的好感，不深但干净；别把“有点意思”脑补成“非你不可”。", "第三张 · 宝剑九逆：别在焦虑的夜里表白——逆位说，你最大的敌人是深夜的内耗，表白要在你状态好的白天，清醒地说。"], "scan": "是非题 2 正 1 逆，倾向“可以，但别急”；两张侍从：关系还在“前青春期”，节奏比答案重要。", "conclusion": "牌的倾向是“可以捅，但别现在”。先做两件事：把互动从“偶遇”升级到“有由头的单独相处”（一起吃饭、一起做项目），看他接不接招；等你不再失眠内耗了再表白。表白方式别搞大的——轻松直接的一句话，比仪式感更适合两个侍从的阶段。", "source": "练习案例 · 虚构示意"}, {"id": "c19", "title": "异地恋：刚在一起就要异国两年", "question": "刚确定关系一个月，他就要去国外读两年书，这段感情还有必要开始吗？", "cat": "感情", "spread_id": "s6", "cards": [{"id": 37, "pos": "对方的心情", "rev": false}, {"id": 0, "pos": "自己的状况", "rev": false}, {"id": 55, "pos": "相处方式", "rev": false}, {"id": 24, "pos": "周遭环境", "rev": false}, {"id": 10, "pos": "关系结果", "rev": false}], "steps": ["对方的心情 · 圣杯二：他是认真的——圣杯二是最对等的一张牌，他想跟你一起面对，不是通知你。", "自己的状况 · 愚人：你现在是“想跳又不敢跳”——愚人说，这段感情的开局就是冒险，怕是正常的，不怕才奇怪。", "相处方式 · 宝剑六：相处模式会是“一起渡河”——宝剑六是同舟共济，异地最大的敌人不是距离，是“各过各的”，这张牌说你们能做到同频。", "周遭环境 · 权杖三：环境是支持的——朋友、家人都看好，权杖三是“远方的船会回来”，外界不添堵。", "关系结果 · 命运之轮：轮子站在你们这边——这段关系有“天时”，两年后的重逢大概率是向上的转折，不是散场。"], "scan": "大牌 2/5 全正位——开局即异地的关系，牌面意外地顺；宝剑六＋权杖三：距离是物理的，心可以是同步的。", "conclusion": "可以开始，但要用“异地模式”重新签约：① 把联系频率、见面计划、各自的底线先谈死（圣杯二的对等要落成规则）；② 每年至少见两次，钱和时间提前攒；③ 约定“半年复盘”——轮子转的时候，两个人都要在车上。异地杀不死认真的感情，杀死的是“顺其自然”。", "source": "练习案例 · 虚构示意"}, {"id": "c20", "title": "相亲：这个人靠谱吗", "question": "相亲认识一个月，见了三次，感觉人还行但总觉得摸不清，能继续接触吗？", "cat": "感情", "spread_id": "s3", "cards": [{"id": 47, "pos": "过去", "rev": false}, {"id": 51, "pos": "现在", "rev": false}, {"id": 25, "pos": "未来", "rev": false}], "steps": ["过去 · 圣杯骑士：初见印象分是高的——他表现得体、殷勤，骑士的浪漫是真的，但骑士也代表“还在展示期”。", "现在 · 宝剑二：你现在卡在“信息不够”——蒙着眼做判断，宝剑二说别急着下结论，也别急着投入，先收集信息。", "未来 · 权杖四：按现在走下去，能走到“稳定见面”的阶段——权杖四是庆祝和小确幸，关系会进入轻松期，但“靠谱”还要更久才能验证。"], "scan": "圣三角看新关系轨迹（同阵不同用法）：全正位，节奏健康；宝剑二在“现在”位——摸不清是正常的，因为信息本来就不够。", "conclusion": "继续接触，但把“摸清”变成具体动作：多见他和朋友相处的样子、多聊他对分歧的态度（别只聊爱好）。权杖四承诺的是“相处愉快”，不是“人品担保”——靠谱要三个月后才看得清，现在只管享受了解的过程。", "source": "练习案例 · 虚构示意"}, {"id": "c21", "title": "复合：他说改了，是真的吗", "question": "前任当初出轨分的手，现在回来说断干净了、想复合，我该怎么鉴定他的诚意？", "cat": "感情", "spread_id": "s7", "cards": [{"id": 56, "pos": "我的心态", "rev": true}, {"id": 15, "pos": "对方的心态", "rev": false}, {"id": 52, "pos": "过去", "rev": false}, {"id": 14, "pos": "现在", "rev": true}, {"id": 18, "pos": "未来发展", "rev": false}, {"id": 40, "pos": "环境", "rev": false}], "steps": ["我的心态 · 宝剑七逆：你不想再被骗第二次——逆位的宝剑七是“吃一堑”，你的警惕是健康的，别为此自责。", "对方的心态 · 恶魔：他心里还有“瘾”——恶魔正位是全场最重的警告：他回来的驱动力里，欲望和占有欲的成分大于悔改。", "过去 · 宝剑三：伤口是真实的——这张牌替你记着疼，别为了“他说改了”就删掉这段记忆。", "现在 · 节制逆：现在的“复合谈判”频道是乱的——他急、你怕，两个人根本不在一个节奏上，谈不出结果。", "未来发展 · 月亮：按现在这样复合，未来是月亮——看不清、猜不透，旧伤会在某个深夜重新疼起来。", "环境 · 圣杯五：共同朋友都在劝“别回头”——环境不看好，但决定权在你，别人的意见只是参考。"], "scan": "人际关系阵做诚意鉴定（同阵不同用法）：恶魔在“对方心态”位＋月亮收尾——诚意存疑，这是鉴定类案例的教科书牌型。", "conclusion": "牌的鉴定结果：诚意不足，至少现在不足。给他设硬指标：① 断联证明（不是口头说）；② 至少 3 个月的“考察期”，期间不复合只观察；③ 谈一次“出轨为什么会发生”的深谈，答不上来就是没复盘。恶魔＋月亮的组合，宁可错杀，不可错信。", "source": "练习案例 · 虚构示意"}, {"id": "c22", "title": "分手断联：他还会回来吗", "question": "分手两个月了，他彻底断联，我是继续等他回头，还是主动断了往前走？", "cat": "感情", "spread_id": "s5", "cards": [{"id": 57, "pos": "求问者现况", "rev": false}, {"id": 39, "pos": "选甲的近况（继续等）", "rev": false}, {"id": 23, "pos": "选乙的近况（主动向前）", "rev": false}, {"id": 18, "pos": "选甲的未来", "rev": true}, {"id": 71, "pos": "选乙的未来", "rev": false}], "steps": ["求问者现况 · 宝剑八：你被自己的“万一”困住了——宝剑八的绳子是自己绑的，“等”这个动作本身正在消耗你。", "选甲的近况（继续等）· 圣杯四：等来的大概率是“无视”——圣杯四是递到面前的杯子都不看，他现在没在看你这个方向。", "选乙的近况（主动向前）· 权杖二：向前走的第一步是“拿回选择权”——权杖二站在高处看世界，视野一开，执念就小了。", "选甲的未来（继续等）· 月亮逆：等到最后，迷雾会散——你会看清他不回来不是因为忙，是因为不想；但这个过程要疼很久。", "选乙的未来（主动向前）· 钱币八：向前走是“匠人路”——把心思放回自己身上，学东西、搞事业，三个月后你会感谢现在转身的自己。"], "scan": "二择一对比两条行动线（同阵不同用法）：圣杯四＋月亮逆 vs 权杖二＋钱币八——“等”与“走”的代价写得清清楚楚。", "conclusion": "牌建议选乙：主动向前。给自己设一个仪式性的了断——删掉置顶、收起合照、把“等他”从每日任务里划掉。钱币八承诺的是“越专注自己越有回报”，这不是鸡汤，是牌面算出来的账。他会不会回来不重要了，重要的是你不再为“会不会”付电费。", "source": "练习案例 · 虚构示意"}, {"id": "c23", "title": "新恋情：他是认真的吗", "question": "刚谈了一个月，他每天早安晚安、记得我的喜好，但总觉得“太顺了”不真实，他是认真的吗？", "cat": "感情", "spread_id": "s4", "cards": [{"id": 46, "pos": "问题核心", "rev": false}, {"id": 54, "pos": "障碍或短处", "rev": false}, {"id": 6, "pos": "对策", "rev": false}, {"id": 72, "pos": "资源或长处", "rev": false}], "steps": ["问题核心 · 圣杯侍从：核心是“青涩的真心”——他是认真的，但认真的方式是侍从级的：用力过猛、不太会把握分寸，所以你觉得“太顺”。", "障碍或短处 · 宝剑五：障碍是“你的防御”——过去的伤让你把“好”也当成可疑的，宝剑五说，别用旧战场的规则打新仗。", "对策 · 恋人：对策是“对等回应”——恋人牌说，认真要配认真；你不需要考验他，只需要真实地做自己，看他接不接得住。", "资源或长处 · 钱币九：你的资源是“独立”——你不是非他不可，这种底气恰恰是让一段新感情健康生长的最好土壤。"], "scan": "直指核心做态度鉴定（同阵不同用法）：全正位小牌为主——“太顺”不是陷阱，是侍从式认真的副作用。", "conclusion": "他是认真的，只是“新手级认真”。别考验、别试探，正常交往三个月，是骡子是马自然看清。你的功课只有一个：允许自己被好好对待——宝剑五的防御机制该退役了，钱币九的你值得一段不费力的感情。", "source": "练习案例 · 虚构示意"}, {"id": "c24", "title": "年度运势：转型之年怎么走", "question": "30 岁了，今年想从执行岗转管理岗，这一年整体运势怎么样，重点该抓什么？", "cat": "综合", "spread_id": "s8", "cards": [{"id": 23, "pos": "问题现况", "rev": false}, {"id": 59, "pos": "障碍或援助", "rev": true}, {"id": 19, "pos": "理想状况", "rev": false}, {"id": 1, "pos": "本意", "rev": false}, {"id": 9, "pos": "过去状况", "rev": false}, {"id": 10, "pos": "未来状况", "rev": false}, {"id": 66, "pos": "你的现况", "rev": false}, {"id": 41, "pos": "周围环境", "rev": false}, {"id": 17, "pos": "你的愿望", "rev": false}, {"id": 14, "pos": "最后结果", "rev": false}], "steps": ["问题现况 · 权杖二：你站在高处看全年——有规划、有野心，转管理的念头不是冲动，是看好的地形。", "障碍或援助 · 宝剑十逆：好消息——最疼的那段已经过去了；逆位的宝剑十说，别再为去年的伤反复复盘，伤口结痂了就往前走。", "理想状况 · 太阳：你想要的是“被看见”——太阳要的是高光，不是苟着；转管理的目标和你内心的愿望是一致的。", "本意 · 魔术师：你手里什么都有——能力、人脉、对业务的理解；魔术师说，缺的从来不是牌，是“出牌”的决心。", "过去状况 · 隐士：过去一年你在“修炼内功”——沉得住气、补短板，这段蛰伏是今年的底气，不是浪费。", "未来状况 · 命运之轮：轮子今年是向上的——有贵人、有机会窗口，但轮子只载“准备好的人”，别在机会来时掉链子。", "你的现况 · 钱币三：你现在是“匠人”状态——手艺精，但缺“被看见的舞台”；今年的功课是把作品摆出去。", "周围环境 · 圣杯六：环境是友善的——老同事、老领导都愿意拉你一把，别不好意思开口求助。", "你的愿望 · 星星：愿望很正——你想成为“能带人的人”，星星照的是长期主义者，急功近利的人看不见它。", "最后结果 · 节制：收尾是节制——今年不会一飞冲天，但会“稳稳地好起来”；转管理大概率在下半年水到渠成。"], "scan": "塞尔特十字做年度简化扫描（注：牌阵库已收录 s9 十二宫牌阵（12 宫位），本案用 s8 做简化年度总览，完整版可用 s9 展开）：大牌 6/10，命运之轮＋太阳＋节制——向上的一年，节奏是“稳”。", "conclusion": "今年宜“主动求变、稳步推进”。上半年：把作品和成绩摆出去（钱币三），主动跟领导谈转管理的意愿（魔术师）；下半年：机会窗口大概率出现（命运之轮），接住就行。记住节制：别all in式转岗，先争取“带小团队/负责项目”的过渡身份，稳稳地好起来。", "source": "练习案例 · 虚构示意"}, {"id": "c25", "title": "城市：留广州还是回老家", "question": "在广州漂了 5 年，工资涨不动、买房无望，老家父母催回去考编，留还是回？", "cat": "综合", "spread_id": "s5", "cards": [{"id": 51, "pos": "求问者现况", "rev": false}, {"id": 28, "pos": "选甲的近况（留广州）", "rev": false}, {"id": 41, "pos": "选乙的近况（回老家）", "rev": false}, {"id": 73, "pos": "选甲的未来", "rev": false}, {"id": 18, "pos": "选乙的未来", "rev": false}], "steps": ["求问者现况 · 宝剑二：你不是没答案，是两个选项都有代价所以僵住了——先承认“没有完美选项”，再选。", "选甲的近况（留广州）· 权杖七：留下＝继续守擂台——竞争、房租、内卷一个不少，但你是守得住的人，权杖七说你有这个体力。", "选乙的近况（回老家）· 圣杯六：回去＝回到舒适区——亲情、熟人、慢生活，圣杯六是温暖的，但也可能是“温水”。", "选甲的未来（留广州）· 钱币十：长线看，留下的终点是“扎根”——钱币十是安居乐业，5 年的漂换来的是“留下来”的资格，不是白漂。", "选乙的未来（回老家）· 月亮：回去的长线是“未知的雾”——考编不一定上、回去不一定适应，月亮说别把老家想象成避风港，它也有它的难。"], "scan": "二择一城市线：钱币十 vs 月亮——“留”的终点看得见，“回”的终点在雾里；但圣杯六提醒，别把亲情需求也算进城市账里。", "conclusion": "牌倾向“留”，但有个前提：把“要不要回老家”和“要不要多陪父母”拆成两件事——前者牌说留（钱币十），后者可以用“每年固定回去住一阵＋把父母接来过冬”解决（圣杯六）。如果留下，接下来两年是关键期：要么升职加薪、要么副业起量，得让“留”这件事配得上它的代价。", "source": "练习案例 · 虚构示意"}, {"id": "c26", "title": "职业方向：转产品还是深耕运营", "question": "做了 3 年运营，现在有个转产品经理的机会，但怕转过去从零开始，该转还是深耕？", "cat": "综合", "spread_id": "s5", "cards": [{"id": 1, "pos": "求问者现况", "rev": false}, {"id": 61, "pos": "选甲的近况（转产品）", "rev": false}, {"id": 34, "pos": "选乙的近况（深耕运营）", "rev": false}, {"id": 7, "pos": "选甲的未来", "rev": false}, {"id": 3, "pos": "选乙的未来", "rev": false}], "steps": ["求问者现况 · 魔术师：你手里的牌是“可迁移能力”——数据 sense、用户理解、跨部门协作，转产品不是从零开始，是换赛道。", "选甲的近况（转产品）· 宝剑骑士：转过去的开局是“快”——学东西快、出活快，但骑士也意味着“容易翻车”，前半年是试用期心态，别飘。", "选乙的近况（深耕运营）· 权杖王后：深耕是“稳中带旺”——你在运营上已经是王后位了，继续走是舒适且体面的。", "选甲的未来（转产品）· 战车：长线看，转产品是“开疆”——战车拉得动，天花板更高，但你要一直踩油门。", "选乙的未来（深耕运营）· 女皇：长线看，深耕是“结果”——女皇是收获期，3 年后你会是运营专家，但天花板看得见。"], "scan": "二择一职业线：战车 vs 女皇——“更高的天花板”对“更确定的收获”，这是 30 岁前后最经典的一道题。", "conclusion": "看你现阶段要什么：要天花板，转（战车）；要确定性，留（女皇）。牌给了一个折中建议：先接“运营＋产品” hybrid 的活（比如负责增长方向），用半年验证自己喜不喜欢产品思维，再决定转不转——魔术师的本钱，值得一次有退路的试探。", "source": "练习案例 · 虚构示意"}, {"id": "c27", "title": "涨租 30%：搬还是不搬", "question": "房东说下个月涨租 30%，这小区住惯了但肉疼，搬还是咬牙续？", "cat": "综合", "spread_id": "s2", "cards": [{"id": 67, "pos": "第一张", "rev": false}, {"id": 53, "pos": "第二张", "rev": false}, {"id": 16, "pos": "第三张", "rev": false}], "steps": ["第一张 · 钱币四：你现在的模式是“守财”——涨 30% 的疼是真实的，钱币四说别为“住惯了”付溢价，舒适区也有标价。", "第二张 · 宝剑四：但也别冲动搬——宝剑四说，先歇一歇再决定，带着情绪找房容易踩坑；给自己两周冷静期。", "第三张 · 塔：塔是全场定音——这地方的“稳”本来就是幻觉，涨租只是第一块砖；与其被动挨涨，不如主动搬。"], "scan": "是非题 3 正，倾向明确：搬。塔在第三张——“住惯了”的安全感是纸糊的。", "conclusion": "搬。但按宝剑四的节奏搬：两周内看房、列清单（通勤/预算/周边三条硬线），别为了赌气当天就签。塔牌的另一层意思是：搬完别回头看——旧小区的“好”会在你搬走后自动美化，别信。", "source": "练习案例 · 虚构示意"}, {"id": "c28", "title": "独居：要不要养只猫", "question": "独居两年，特别想养只猫陪伴，但工作经常出差，怕照顾不好，养还是不养？", "cat": "综合", "spread_id": "s4", "cards": [{"id": 41, "pos": "问题核心", "rev": false}, {"id": 58, "pos": "障碍或短处", "rev": true}, {"id": 65, "pos": "对策", "rev": false}, {"id": 19, "pos": "资源或长处", "rev": false}], "steps": ["问题核心 · 圣杯六：核心是“想要被需要”——圣杯六的温柔是真的，你想养猫不是一时兴起，是情感需求到了。", "障碍或短处 · 宝剑九逆：障碍是“过度焦虑”——逆位说，宝剑九的深夜戏码正在退场：你担心的“照顾不好”，多半是深夜里被放大的想象，白天冷静下来看，并没有那么不可收拾；出差确实有影响，但不是死刑。", "对策 · 钱币二：对策是“先排好班”——钱币二是 juggling：出差找好寄养/上门喂猫的人、自动喂食器备好，把“万一”变成“预案”再养。", "资源或长处 · 太阳：你的资源是“稳定的生活”——独居、有固定收入、有爱心，太阳说你是能养好猫的人，别低估自己。"], "scan": "直指核心做养宠决策（同阵不同用法）：圣杯六＋太阳——情感需求真实、条件具备，唯一的坎是出差的预案。", "conclusion": "可以养，但顺序是：先搞定出差预案（寄养人选＋自动设备），再去接猫。建议从领养成年猫开始（性格稳定、不用熬夜奶），别从两个月的小奶猫起手。太阳牌说，这只猫会是你独居生活里最对的决定之一。", "source": "练习案例 · 虚构示意"}, {"id": "c29", "title": "副业：要不要辞职全职做", "question": "自媒体副业月入过万了，超过了工资的一半，要不要辞职全职干？", "cat": "综合", "spread_id": "s5", "cards": [{"id": 10, "pos": "求问者现况", "rev": false}, {"id": 0, "pos": "选甲的近况（全职）", "rev": false}, {"id": 71, "pos": "选乙的近况（保持副业）", "rev": false}, {"id": 16, "pos": "选甲的未来", "rev": false}, {"id": 14, "pos": "选乙的未来", "rev": false}], "steps": ["求问者现况 · 命运之轮：轮子正在转——副业起量是“天时”，不是你的错觉；但轮子转的时候，人容易高估自己。", "选甲的近况（全职）· 愚人：全职的开局是“自由落体式快乐”——时间自由、没人管，愚人的前三个月会很爽。", "选乙的近况（保持副业）· 钱币八：保持副业是“匠人节奏”——白天上班、晚上打磨，累但稳，钱币八攒的是基本功。", "选甲的未来（全职）· 塔：全职的长线有塔——收入波动、社保断缴、一个人扛事，至少一样会塌；塔不是不让你去，是让你“带着安全带”去。", "选乙的未来（保持副业）· 节制：保持副业的长线是“调和”——主业兜底、副业生长，两条腿走路，节制说这是最优解。"], "scan": "二择一全职化（同阵不同用法）：愚人＋塔 vs 钱币八＋节制——“爽三个月”对“稳三年”，账算得很清楚。", "conclusion": "现在别辞。设两条“辞职线”：① 副业连续 6 个月收入超过工资；② 存够 12 个月生活费的安全垫。两条都到了，塔就塌不下来，再带着安全带跳（愚人）。现在辞，是拿塔当滑梯玩。", "source": "练习案例 · 虚构示意"}, {"source": "练习案例 · 虚构示意", "title": "断联五个月：还能复联吗", "id": "c30", "cards": [{"id": 37, "pos": "过去基础", "rev": false}, {"id": 40, "pos": "我的现状", "rev": false}, {"id": 9, "pos": "对方的现状", "rev": false}, {"id": 41, "pos": "我的真实想法", "rev": false}, {"id": 63, "pos": "对方的真实想法", "rev": false}, {"id": 52, "pos": "分手根本原因", "rev": false}, {"id": 14, "pos": "复合建议", "rev": false}, {"id": 18, "pos": "盲区", "rev": false}, {"id": 43, "pos": "未来走向", "rev": false}], "steps": ["过去基础 · 圣杯二：先看画面——两人隔桌各递出一只杯，杯口上方是交缠的双蛇杖。当初是真正的双向奔赴，杯子是同时递出去的，这段感情的底子没有造假。", "我的现状 · 圣杯五：裹黑斗篷的人低头盯着三只翻倒的杯，背后还有两只满杯立着、桥就在不远处——你满眼都是“断掉”的那部分，还没转身去看剩下的可能。", "对方的现状 · 隐士：老人披灰袍站在雪顶，一手拄杖、一手提着一盏只照亮自己脚下的灯——他不是在等谁，是一个人在暗处想事情；这个阶段外人敲门，他也不会开。", "我的真实想法 · 圣杯六：两个孩子在石屋前交换一只开着花的杯——你想复联，一大半想的是回到从前那个版本：那时候的你们，不是现在这两个人。", "对方的真实想法 · 宝剑国王：国王正面端坐，宝剑斜举过肩，另一只手摊开在膝上——他的理性已经开过庭了：那句重话被他当成判决书，感情在心里结了案。", "分手根本原因 · 宝剑三：一颗红心被三把剑同时穿透，背景是密密的雨——根本原因不是不爱，是那次争吵里话说得太狠，伤口到今天还在下雨。", "复合建议 · 节制：天使一脚踩岸、一脚浸水，把水在两只杯之间来回倒——建议不是“复合”或“放弃”二选一，是先把节奏调回来：从普通朋友式的偶尔联系开始，让水流先通。", "盲区 · 月亮：双塔之间挂着月亮，狗和狼对月嗥叫，水里的小龙虾正往岸上爬——你没看清的是：一个点赞可能只是深夜随手，月光下的影子最容易被看成信号。", "未来走向 · 圣杯八：人披红斗篷，背对八只叠得整整齐齐的杯，拄杖往月亮升起的山里走——走向更像这样：不是谁回来敲门，而是其中一个人先转身，去找那只缺掉的第九杯。"], "spread_id": "s17", "conclusion": "复联的通道没有完全关死，但开的不是正门。先按节制的节奏来：把他当回一个普通联系人，联系里不提当年、不问态度；他若持续回应，门会自己开缝。最忌讳的是拿点赞当圣旨冲过去表态——月亮说得很清楚，你现在最容易输给自己的想象。", "cat": "感情", "scan": "九张里圣杯占四张、宝剑两张——情分仍是主调，决裂的刀也真实存在；大牌三张（隐士、节制、月亮）张张向内，这不是一拍两散的小事。全阵无逆位：局势并不浑浊，卡点很具体——他关了门，你盯着旧杯。", "question": "分手五个月了，当时我说了重话，他直接断联；最近他突然给我朋友圈点了个赞，我们还有复联的可能吗？"}, {"source": "练习案例 · 虚构示意", "title": "冷战一周：谁先低头", "id": "c31", "cards": [{"id": 54, "pos": "我的想法", "rev": false}, {"id": 68, "pos": "对方的想法", "rev": true}, {"id": 39, "pos": "关系现状", "rev": false}, {"id": 37, "pos": "未来发展", "rev": false}], "steps": ["我的想法 · 宝剑五：画面里的人抱着三把剑回头笑，地上还丢着两把，两个人正转身离场——你的心态是“我赢了道理”，可赢家抱着一堆剑，怀里没有人。", "对方的想法 · 钱币五逆：正位时是两个人在雪夜里走过亮着灯的教堂却进不去；逆位把画面翻了回来——他开始往那扇有光的窗户走了。想缓和是真的，只是拉不下脸先开口，他在等一个台阶。", "关系现状 · 圣杯四：树下的人抱着胳膊，面前摆着三只杯，天上又递来第四只，他看都不看——你们不是没感情，是倦怠：同样的示好递过来，第一反应都是“懒得接”。", "未来发展 · 圣杯二：两个人面对面，各递出一只杯——和好的画面牌已经画出来了：不需要谁跪下道歉，需要一次同时递杯的动作，比如一顿不谈对错的饭。"], "spread_id": "s13", "conclusion": "能和好，而且不用等太久。谁先低头不重要，重要的是低头的方式：别发小作文复盘对错，用圣杯二的办法——递一个具体的、轻松的邀约过去。他那边逆位已经转身，你递杯，他多半会接。", "cat": "感情", "scan": "四张里圣杯两张、没有大牌——这是日常摩擦级别的冷战，不是关系危机。关键信号在钱币五逆：对方那边先出现了“往暖处走”的动静，僵局的冰已经从他那一侧开始化。", "question": "因为他打游戏冷落我大吵了一架，冷战一周了，这架还和得好吗？要等他先低头吗？"}, {"source": "练习案例 · 虚构示意", "title": "游戏搭子：要不要表白", "id": "c32", "cards": [{"id": 46, "pos": "第一张", "rev": false}, {"id": 56, "pos": "第二张", "rev": true}, {"id": 66, "pos": "第三张", "rev": false}], "steps": ["第一张 · 圣杯侍从：青年端着一只杯，杯里探出一条小鱼回头看他——好感是真的，而且是藏不住的那种：你们聊天里满溢的分享欲，就是这条探头的鱼。", "第二张 · 宝剑七逆：正位的人抱着五把剑踮脚溜走、地上还剩两把，是“有话藏着掖着”；逆位让藏着的姿势翻了面——再不摊开，这份心思会一直耗在偷偷摸摸里，翻面就是催你说破。", "第三张 · 钱币三：工匠站在凳子上雕花，两个人拿着图纸在旁商量——你们的关系有真实的地基：三年搭子不是萍水相逢，是一起“建过东西”的交情，表白不是从零开始。"], "spread_id": "s2", "conclusion": "可以表白，但顺序别反：先约一次线下见面，把“网友滤镜”这一关过了，再在见面之后表态。宝剑七逆最怕隔着屏幕把想象当了解；钱币三说你们的交情经得起见面这一关——见了再说，成功率反而更高。", "cat": "感情", "scan": "三张两正一逆，按是非题牌阵的读法，圣杯打头、整体倾向偏“可”；唯一的逆位落在宝剑七——“可”的前提是把话说清、说全，其中包括你们还没见过面这个事实。", "question": "打游戏认识的搭子，聊了三年特别合拍，但从没见过面，我想跟他表白，靠谱吗？"}, {"source": "练习案例 · 虚构示意", "title": "新对象总借钱：他图什么", "id": "c33", "cards": [{"id": 1, "pos": "人物牌", "rev": true}, {"id": 61, "pos": "表面理由", "rev": false}, {"id": 38, "pos": "情感需求", "rev": false}, {"id": 73, "pos": "核心欲望", "rev": true}, {"id": 70, "pos": "现实利益", "rev": false}, {"id": 15, "pos": "隐秘执念", "rev": false}], "steps": ["人物牌 · 魔术师逆：魔术师一手指天、一手指地，桌上四件工具齐全，本是“万事俱备”；逆位把这套姿势翻了面——工具还在手里，却用在了变戏法上。这个人的关键词是：话术大于实货。", "表面理由 · 宝剑骑士：骑士骑白马举剑疾驰，披风和鬃毛全被风吹起——他的说法有个共同点：快、满、笃定。“下周就回款”“项目马上结”，全是冲锋式的承诺，细节经不起追问。", "情感需求 · 圣杯三：三个女子举杯围成一圈起舞，脚边是丰收的果子——他真正要的是这个：热闹、被围着、有人捧场。跟你在一起，他享受的是“被人当回事”的感觉。", "核心欲望 · 钱币十逆：正位的钱币十是拱门下三代同堂、十枚钱币排成生命之树；逆位把圆满图景倒了过来——他渴望的是“过上富足体面日子”这个画面本身，想要结果，不想走攒钱的过程。", "现实利益 · 钱币七：农人拄着锄头，望着藤上七枚长了一半的钱币——说句公道话：他确实在等一笔没落地的钱，月底借小钱更像真周转，不全是演的。", "隐秘执念 · 恶魔：恶魔坐在高处，男女脖子上的锁链松松垮垮、伸手就能摘，头上却慢慢长出角——他自己未必承认的执念是“一把翻身”：越信捷径，越离不开借钱续命的循环。"], "spread_id": "s16", "conclusion": "结论分两层：他不是设局骗钱的职业骗子，但他嘴里的财务状况注了水，借钱这件事必须停。做法很明确：在他把“那笔没落地的钱”变成到账记录之前，不再出借任何金额；感情可以慢慢看，账先一笔一笔核清——魔术师逆最怕的，就是你把戏法当魔法信下去。", "cat": "感情", "scan": "六张里大牌两张（魔术师逆、恶魔），钱币两张（钱币十逆、钱币七），且都落在「核心欲望」与「现实利益」的钱位上——题眼因此明确：钱，和围着钱转的人设。两张大牌一张逆位、一张暗面，说明问题是结构性的，不是一次借钱的小误会。", "question": "新认识的对象自称做外贸收入不错，可总在月底找我借小钱周转，他到底有没有骗我？"}, {"source": "练习案例 · 虚构示意", "title": "他会不会来找我", "id": "c34", "cards": [{"id": 31, "pos": "过去", "rev": false}, {"id": 57, "pos": "现在", "rev": false}, {"id": 32, "pos": "未来", "rev": true}], "steps": ["过去 · 权杖十：一个人抱着十根权杖，弯腰往远处的房子走，脸都被杖挡住了——你们后期只剩下“扛着”：沟通变成负重，谁也没力气说话，分开某种意义上是卸货。", "现在 · 宝剑八：穿红衣的女子被蒙眼绑着，身后八把剑插成一排像栅栏，脚边是水洼，绳索其实松松的——红衣是行动的颜色，说明他不是不想动；困住他的是面子和自尊：当初没留话，现在没台阶。", "未来 · 权杖侍从逆：青年双手高举权杖、仰头看杖顶的新芽；逆位让这股仰头的劲矮了下去——未来更可能出现的是一个迟到的、小小的试探（一条消息、一句问候），不是他收拾行李来找你。"], "spread_id": "s3", "conclusion": "直接回答：他大概率不会“来找你”——不是没心，是被自己的面子绑住了，而绳是他自己系的，得他自己解。你能做的是不把门焊死、也不站在门口等；真等到那个试探的小动作出现，接不接、怎么接，到时你说了算。", "cat": "感情", "scan": "三张里两张权杖夹一张宝剑八——“想动”的能量一直都在，卡点只有一个：宝剑八的绳。没有圣杯出现，说明眼下双方都没有把感情摆上台面，未来位的逆位侍从把动静的量级也标好了：小，且迟。", "question": "分手后我换了城市工作，他一句话没留，他还会来找我吗？"}, {"source": "练习案例 · 虚构示意", "title": "暧昧半年：在他眼里我是谁", "id": "c35", "cards": [{"id": 47, "pos": "对方的心意", "rev": false}, {"id": 51, "pos": "关系定位", "rev": false}, {"id": 69, "pos": "真心程度", "rev": false}, {"id": 62, "pos": "对方眼中的我", "rev": false}, {"id": 6, "pos": "关系的可能性", "rev": false}, {"id": 14, "pos": "未来走向", "rev": true}], "steps": ["对方的心意 · 圣杯骑士：骑士骑马缓缓而行，双手把一只杯像献礼一样捧在胸前，盔甲上带着鱼鳞纹——他的心意是浪漫型的：有好感，而且想得很认真，只是步子慢。", "关系定位 · 宝剑二：女子蒙着眼，两把剑交叉挡在胸前，身后是一片平静的海——你们的定位卡在“谁也不先睁眼”：都看得见对方，就是都没肯先把防御放下。", "真心程度 · 钱币六：富人一手端着一架天秤、一手往别人手里放钱币——他给之前是称过分量的：真心有，但他的真心是“量入为出”型，投入多少，取决于你回多少。", "对方眼中的我 · 宝剑王后：王后端坐高处，剑尖笔直朝上，一只手向前伸出，脚边一弯月牙——在他眼里你是清醒、锋利、有主见的那种人：欣赏，也有点怕；知道在你面前糊弄不过去。", "关系的可能性 · 恋人：天使在上方张开双臂，两个人坦诚地站在树下——可能性真实存在，这张牌说的就是“到了要选的时候”：再往前一步，关系会变成另一种东西。", "未来走向 · 节制逆：天使把水在两只杯之间来回倒，本该流个不停；逆位让水流断了节奏——走向的最大变数是节奏：他是慢热的骑士，你是利落的王后，一快一慢耗下去，好感会被日常磨掉。"], "spread_id": "s14", "conclusion": "在他眼里，你是“宝剑王后”——这是敬重，也是距离。想改变定位，靠的不是再暗示：他是称量型的人，你越追，他越往后称；反而是你利落地把话挑明一次，给不给答案都干脆，他的天秤才会真正往你这边倾。拖过了节奏窗口，节制逆就是结局。", "cat": "感情", "scan": "六张里三张是人物特写（骑士捧杯、富人持秤、王后端坐）——这段关系全是“人对人”的互相端详，缺少事件推进。大牌两张一正一逆：恋人给了可能性，节制逆给了时限警告。", "question": "和同事暧昧半年了，一直没定性，我想知道在他眼里我到底算什么？"}, {"source": "练习案例 · 虚构示意", "title": "谈婚论嫁：这段关系能长久吗", "id": "c36", "cards": [{"id": 72, "pos": "我的心态", "rev": false}, {"id": 4, "pos": "对方的心态", "rev": false}, {"id": 45, "pos": "过去", "rev": false}, {"id": 68, "pos": "现在", "rev": false}, {"id": 11, "pos": "未来发展", "rev": false}, {"id": 16, "pos": "环境", "rev": true}], "steps": ["我的心态 · 钱币九：女子独自站在葡萄架下，手上托着一只小鸟，九枚钱币在身边排得整整齐齐——你的心态底色是“我自己挣来的安稳很珍贵”：你不抗拒结婚，怕的是合并之后，这份自在没了。", "对方的心态 · 皇帝：帝王坐在四只牡羊头装饰的石座上，红袍、宝球、权杖王牌样不少——他想的是把“结构”定下来：领证、买房、按部就班。在他那里，定了名分才叫安心。", "过去 · 圣杯十：彩虹在天上弯成弧，十只杯排在彩虹里，一家人在下面张开手臂——你们的感情地基是真材实料：三年不是凑合过来的，这一点吵架吵不掉。", "现在 · 钱币五：两个人衣衫单薄地走在雪地里，旁边就是亮着暖光的教堂窗，他们却低着头走过——现在的卡点非常具体，就是钱：不是没办法，是“合并财务”这扇有光的窗，你们还没一起推开过。", "未来发展 · 正义：法官一手托天秤、一手持剑，坐在两根柱子之间——能不能长久，不取决于还爱不爱，取决于规则谈不谈得平：房子写谁名、双方父母的钱接不接，谈成白纸黑字，就长久。", "环境 · 高塔逆：雷劈塔顶、王冠翻落、人往下坠的画面被逆位按住了——外部冲击（房价、父母催婚）不是不存在，只是不以“突然崩塌”的方式来；它会变成慢性的内部消耗，一点一点磨你们。"], "spread_id": "s7", "conclusion": "能长久，但有一道必答题：把钱的事从“一谈就吵”变成“坐下来谈完”。正义给的方法是把模糊地带逐项落纸——各自保留多少独立账户（照顾你的钱币九）、共同支出怎么分、父母的钱接不接。谈成的那天，皇帝要的秩序和你要的自在，能同时成立。", "cat": "感情", "scan": "六张里大牌三张，其中皇帝、正义两张正位压阵——结构其实稳；唯一的逆位落在环境位。圣杯十打底、钱币五卡壳，一暖一冷对比鲜明：问题不在你们之间，在“钱与规则”这道还没做的功课上。", "question": "在一起三年，感情没问题，可一谈钱和双方父母就吵，这段关系能走到结婚、走得长久吗？"}, {"source": "练习案例 · 虚构示意", "title": "分开一个月：他有没有在想我", "id": "c37", "cards": [{"id": 41, "pos": "对方的心情", "rev": false}, {"id": 58, "pos": "自己的状况", "rev": false}, {"id": 23, "pos": "相处方式", "rev": false}, {"id": 10, "pos": "周遭环境", "rev": false}, {"id": 46, "pos": "关系结果", "rev": true}], "steps": ["对方的心情 · 圣杯六：两个孩子在石屋前交换一只开着花的杯——他在想你，这点不用怀疑；但他想的是“从前”：花开在杯里的那种好时光，不是现在的你们。", "自己的状况 · 宝剑九：人半夜从床上坐起，双手捂脸，墙上挂着九把剑——你想他的方式是疼的：失眠、做梦、反复点开对话框。同样是想，你这份的浓度比他高得多。", "相处方式 · 权杖二：人站在城楼上，一手扶着权杖、一手托着小小的地球，望向远处的海——你们现在的相处方式就是“远望”：隔着距离各自看着，谁也没有走近一步的动作。", "周遭环境 · 命运之轮：大轮盘在转，斯芬克斯蹲在顶上——环境在推着两个人往前走：他的新工作、你的新安排都在换挡，想念发生在轮子转动的间隙里，不占主位。", "关系结果 · 圣杯侍从逆：青年端着杯，杯里的鱼探出头；逆位让鱼缩了回去——结果是：想念不会变成消息。他的想停在心里，你的想也最好慢慢停在心里，别替他把鱼捞出来。"], "spread_id": "s6", "conclusion": "答案是：有，他在想你——圣杯六不会说谎。但要分清“想”和“会回来”是两回事：结果位的侍从逆把话说得很明白，想念到他那里就停住了，不会往前多走一步。你可以为这份双向的想念心软三分钟，然后按宝剑九的账算：别让他的想念，继续收你的失眠费。", "cat": "感情", "scan": "五张里圣杯两张、一张逆位落在结果——“想”是双向的，“动”是单向缺席的。大牌只有环境位的命运之轮：这件事的走向不由你们的心情决定，由各自生活的轮子决定。", "question": "和平分手一个多月了，是他提的异地太累。最近总梦见他，他那边……有没有在想我？"}, {"source": "练习案例 · 虚构示意", "title": "分手三个月：他过得怎么样", "id": "c38", "cards": [{"id": 77, "pos": "总览", "rev": false}, {"id": 59, "pos": "过去", "rev": false}, {"id": 40, "pos": "现在", "rev": false}, {"id": 24, "pos": "未来", "rev": false}], "steps": ["总览 · 钱币国王：国王坐在葡萄藤缠绕的王座上，一手按着大钱币，脚下是丰收的园子——总览先给结论：他的“盘子”在变大。升职是真的，日子在物质和事业面上是往上走的。", "过去 · 宝剑十：人面朝下伏地，十把剑插满后背，远处天已破晓——别以为只有你疼：分手那阵他在牌面上也是“插满剑”的状态，只是他的处理方式是趴过去、不出声，然后等天亮。", "现在 · 圣杯五：人裹着黑斗篷，低头盯着三只翻倒的杯，背后两只满杯立着——现在的问题在情绪层：体面归体面，他心里有一块是空的，倒掉的杯子还没扶起来；你听说的那场病，多半就病在这里。", "未来 · 权杖三：红衣人站在高处望着三艘船出港——他的重心会继续往外走：更大的项目、更远的地方。未来这张牌里没有回望，只有远方，你们的生活半径会越拉越开。"], "spread_id": "s19", "conclusion": "总结成一句：他过得不错，但不是毫无代价的那种不错。升职、体面、往前走都是真的，圣杯五那块空也是真的——只是那块空不会由你来填了。知道这些对你最大的用处，是把“他是不是过得不好、是不是还等我”这类猜测结清：他的船已经出港，你的也该解缆了。", "cat": "感情", "scan": "四张一头一尾都是“向外扩张”的牌（钱币国王、权杖三），中间夹着宝剑十与圣杯五——他的故事线是“带着伤往前走”：事业面全线向上，情绪面有一格没补上。没有一张牌指向回头。", "question": "分手三个月了，听说他升了职，又听说他病了一场，他现在到底过得怎么样？"}, {"source": "练习案例 · 虚构示意", "title": "气话分手：他还会主动来吗", "id": "c39", "cards": [{"id": 62, "pos": "问题核心", "rev": true}, {"id": 59, "pos": "障碍或短处", "rev": false}, {"id": 1, "pos": "对策", "rev": false}, {"id": 41, "pos": "资源或长处", "rev": false}], "steps": ["问题核心 · 宝剑王后逆：王后的剑本该笔直朝上、目光朝前；逆位让剑尖偏了、目光也收了回来——核心在那句气话上：话说得太绝，不但堵了他的路，你自己现在也端着，下不来这个台。", "障碍或短处 · 宝剑十：人面朝下伏在地上，十把剑插满后背，但远处的天已经破晓——最大的障碍是“定性”：在他心里，这段关系已经被宣判结束、翻了篇；破晓说明他疼完之后，正打算往新生活里走。", "对策 · 魔术师：一手指天、一手指地，桌上权杖、圣杯、宝剑、钱币四样工具齐备——对策是“搭台”：他不会平白无故来找你，但一次自然的相遇可以由你创造：共同朋友的局、拿他擅长的事请教一下，台搭好了，人就来了。", "资源或长处 · 圣杯六：两个孩子在花园里交换一只开着花的杯——你手里最大的资源是共同记忆的温度：老地方、老梗、他对你的了解，都没过期。桥还在，只是需要你先走一步。"], "spread_id": "s4", "conclusion": "直接答你：他主动来找的概率低，宝剑十的“已结束”是他的当前定性。但魔术师加圣杯六给了另一条路：你若真的后悔，就别等风来，自己搭一次台——理由要轻、场合要自然，给他一个不用先低头也能出现的入口。等他“主动”，等来的会是他破晓之后的新生活。", "cat": "感情", "scan": "四张里宝剑占两张且一张逆位——这件事的战场在“话怎么说”，不在“心还在不在”。大牌只有对策位的魔术师一张：主动权这张牌，恰好发在你手里。", "question": "分手是我气头上提的，现在特别后悔，他还会不会主动来找我？"}, {"source": "练习案例 · 虚构示意", "title": "转行烘焙：现在辞职行吗", "id": "c40", "cards": [{"id": 71, "pos": "适配度", "rev": false}, {"id": 24, "pos": "发展空间", "rev": false}, {"id": 38, "pos": "人际关系", "rev": false}, {"id": 77, "pos": "领导的看法", "rev": false}, {"id": 70, "pos": "注意事项", "rev": true}, {"id": 22, "pos": "其他机会", "rev": false}], "steps": ["适配度 · 钱币八：匠人坐在工作凳上，一枚一枚雕着钱币，身后的架子上成品排成一列——适配度回答得很干脆：你是手艺型的人，烘焙的“在重复里出精度”正对你的性子，这不是三分钟热度。", "发展空间 · 权杖三：红衣人背对着我们站在高处，手扶一根权杖，望着三艘船慢慢出港——远景是有的：版图已经展开；但船才刚出港，靠岸要时间。发展空间成立，周期以年计。", "人际关系 · 圣杯三：三个女子举杯围圈起舞——同行的小圈子气氛不错：烘焙这行靠口碑和互相介绍客源，你业余接单攒下的人脉接得住你，不是从零开始。", "领导的看法 · 钱币国王：国王坐在葡萄藤缠绕的王座上，一手按着一枚大钱币——现单位领导是务实型的人，他看重你的稳；真要走，他大概率会挽留。这也意味着现单位是你转型期的后盾，不必当成敌人。", "注意事项 · 钱币七逆：农人望着藤上半熟的果子；逆位是“急着摘”的姿势——最需要注意的是现金流断层：副业单量看着热闹，还没熟到能替代工资。在果子熟透之前荒了主业的田，是这张牌警告的事。", "其他机会 · 权杖王牌：一只手从云里伸出来，握着一根正在发芽的权杖，远处是山和河——还有一条中间路线：周末市集摊位、节日礼盒团单，先用“副业全职化”试跑一个季度，数据会替你回答辞不辞职。"], "spread_id": "s18", "conclusion": "适配是真的，时机要算。牌的建议：先不裸辞，按权杖王牌的路线试跑一个季度——把副业收入、复购率、单量稳定性记成账；连续三个月副业收入盖过工资的七成，再谈辞职。钱币八的人不怕慢，怕的是断粮时把手艺做贱了。", "cat": "事业", "scan": "六张里钱币占三张——这件事的本质是“手艺与账本”，不是梦想问题。大牌零张：这不是命运级抉择，是经营测算；逆位只有注意事项一张，风险点非常明确，就在钱的时间差上。", "question": "做了五年行政，业余接烘焙单反响不错，想辞职全职做烘焙，现在走行吗？"}, {"source": "练习案例 · 虚构示意", "title": "两个 offer：稳还是闯", "id": "c41", "cards": [{"id": 10, "pos": "求问者现况", "rev": false}, {"id": 67, "pos": "选甲的近况（国企文职）", "rev": false}, {"id": 33, "pos": "选乙的近况（创业公司）", "rev": false}, {"id": 7, "pos": "选甲的未来", "rev": true}, {"id": 17, "pos": "选乙的未来", "rev": false}], "steps": ["求问者现况 · 命运之轮：大轮盘立在中央，斯芬克斯蹲在顶上，蛇与提丰一上一下，四角的活物都在读书——你正站在换挡的轮子上：这次选择换的不是工位，是未来几年的轨道，所以纠结是正常的。", "选甲的近况（国企文职）· 钱币四：人坐在城前，怀里抱一枚钱币、头顶顶一枚、脚下踩两枚——选甲的近况就是这个姿势：稳是真稳，钱和人都“抱住了”；但抱住的另一面是收着、不太动弹。", "选乙的近况（创业公司）· 权杖骑士：红甲骑士骑着跃起的马举杖冲锋，身后是荒丘——选乙的近况是疾驰：项目、节奏、强度一起扑过来，披风都被吹起来了。机会多，颠簸也多。", "选甲的未来 · 战车逆：战车夫的缰绳松了，两只斯芬克斯各走各的方向——甲的远期风险不在待遇，在“方向”：几年后你想调头，会发现缰绳不在自己手里。想动而动不了的闷，比忙更磨人。", "选乙的未来 · 星星：女子跪在水边，一壶水倒进池里、一壶倒在地上，八颗星在天上排开——乙的远期是慢热的滋养：前段的不稳定过去之后，这条路的水，流向的是你真正想成为的样子。"], "spread_id": "s5", "conclusion": "牌不替你选，给你选的方法：甲适合“这三年优先攒钱、安家、给生活留精力”的你；乙适合“这三年优先攒履历和可能性”的你。先问自己这三年到底要攒什么，答案出来，选择自己就出来了。若两边都说得通，星星这张远期牌的分量，建议你多给乙一票。", "cat": "选择", "scan": "二择一两条线牌气分明：甲线钱币四加战车逆，是“稳而收”；乙线权杖骑士加星星，是“快而远”。现况位的命运之轮提醒一句：两条都没有错，错的是拿别人的标准来替自己选。", "question": "同时拿到两个 offer：国企文职稳定但工资低，创业公司运营高薪但听说很卷，我该选哪个？"}];
const MINDMAP={"root": {"title": "塔罗全景", "note": "一张图收下整副牌：它是什么、怎么占、怎么解、怎么学", "children": [{"id": "A", "color": "#e8c66a", "title": "一、这副牌是什么 · 骨架", "note": "先认结构，再认单张", "children": [{"title": "78 张 = 22 大牌 + 56 小牌", "note": "大牌多＝分量重、周期长；小牌多＝日常操作层", "link": {"type": "guide", "anchor": "g1"}}, {"title": "大阿卡纳 · 人生课题线", "children": [{"title": "0 愚人 → 21 世界：一条成长弧", "link": {"type": "theme", "id": "t6"}}, {"title": "三段：1–7 身（显意识）/ 8–14 心（潜意识）/ 15–21 灵（超意识）"}, {"title": "编号即信息：越靠前越向外学，越靠后越向内修"}]}, {"title": "小阿卡纳 · 日常层", "children": [{"title": "四花色 = 四个领域", "link": {"type": "theme", "id": "t5"}, "children": [{"title": "权杖 · 火 — 行动、热情、事业"}, {"title": "圣杯 · 水 — 感情、关系、感受"}, {"title": "宝剑 · 风 — 思考、沟通、冲突"}, {"title": "钱币 · 土 — 金钱、工作、身体"}]}, {"title": "数字 1–10 = 一件事的进程弧", "link": {"type": "theme", "id": "t7"}, "children": [{"title": "1 种子 → 2 选择 → 3 初长 → 4 稳定 → 5 冲突"}, {"title": "6 调和 → 7 考验 → 8 加速 → 9 临门 → 10 完成与溢出"}]}, {"title": "宫廷 16 = 牌里的人", "link": {"type": "theme", "id": "t8"}, "children": [{"title": "角色成长线：侍从 → 骑士 → 王后 → 国王"}, {"title": "性格配方：角色 × 花色元素"}]}]}, {"title": "★ 牌义生成公式", "note": "全图最核心的一条：牌义不是背出来的，是拼出来的", "children": [{"title": "小牌牌义 = 领域（花色）× 阶段（数字）"}, {"title": "宫廷牌义 = 角色 × 元素"}, {"title": "大牌牌义 = 原型课题 ＋ 在旅程中的位置"}]}]}, {"id": "B", "color": "#7fd4c1", "title": "二、一次占卜怎么做 · 流程", "note": "从提问到收尾的七步", "children": [{"title": "1 问对问题", "link": {"type": "theme", "id": "t9"}, "children": [{"title": "开放式，不问是非与宿命"}, {"title": "给时间窗，问“我能做什么”"}]}, {"title": "2 选牌阵", "note": "问题是什么结构，就选什么结构的牌阵", "link": {"type": "tab", "id": "spreads"}}, {"title": "3 抽牌摆牌", "note": "专注于问题，正逆随机出现"}, {"title": "4 先扫结构", "link": {"type": "theme", "id": "t17"}, "children": [{"title": "大牌比例 → 事情的分量"}, {"title": "花色配比 → 能量在哪个领域"}, {"title": "逆位比例 → 能量通不通"}, {"title": "重复数字/主题 → 被强调的信号"}]}, {"title": "5 逐张解", "note": "牌位义 × 这张牌的牌义 × 正逆位状态", "link": {"type": "theme", "id": "t1"}}, {"title": "6 串成故事", "note": "找因果线：主角是谁、转折在哪、往哪走"}, {"title": "7 给建议收尾", "note": "给方向不给命令，决定权在问卜者", "link": {"type": "theme", "id": "t16"}}]}, {"id": "C", "color": "#8fb8ff", "title": "三、解牌的逻辑 · 方法", "note": "牌义之上，还有一层“怎么读”的规矩", "children": [{"title": "三层牌义", "link": {"type": "theme", "id": "t1"}, "children": [{"title": "共通义 — 走到哪都认的骨"}, {"title": "理论义 — 元素/星座/数字推出来的根"}, {"title": "情境义 — 落到这个人的处境里"}]}, {"title": "元素分析", "note": "配比和缺席都说话：哪种能量多、哪种缺位", "link": {"type": "theme", "id": "t5"}}, {"title": "正逆位 = 能量状态", "link": {"type": "theme", "id": "t3"}, "children": [{"title": "正位 — 顺畅地流"}, {"title": "逆位 — 受阻 / 过度 / 转向内里（九式逐一排查）"}]}, {"title": "呼应与重复", "note": "同数字、同花色、同主题反复出现 = 牌在敲黑板"}, {"title": "学理 vs 直觉", "note": "先学理打底；直觉是学理熟透之后的速度，不是捷径", "link": {"type": "theme", "id": "t15"}}]}, {"id": "D", "color": "#d49ae8", "title": "四、学习怎么走 · 路径", "note": "顺序和导览一致：先地图，后细节", "children": [{"title": "导览六站 → 大牌 → 数字 → 宫廷 → 进阶主题 → 牌阵实战", "link": {"type": "tab", "id": "path"}}, {"title": "记忆靠钩子与规律，不靠死背", "link": {"type": "theme", "id": "t2"}}, {"title": "时间问题有专门打法", "link": {"type": "theme", "id": "t13"}}, {"title": "节奏：每日一牌＋单元打勾，学不完顺延不补课"}]}, {"id": "E", "color": "#e8a09a", "title": "五、心法与边界 · 根", "note": "技术之外，决定一位解牌者成色的部分", "children": [{"title": "咨询配比：疗愈 80% / 建议 20%", "link": {"type": "theme", "id": "t16"}}, {"title": "不断生死、不替人做决定、不说绝对化的话"}, {"title": "给自己占容易当局者迷 — 重要问题找人互占"}]}]}};
